'use strict';
const ICONS={menu:'M4 6h16M4 12h16M4 18h16',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',chevron:'m7 10 5 5 5-5',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',cart:'M2 3h3l3 13h11l3-10H6M10 21h.01M18 21h.01',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6',truck:'M1 5h13v12H1V5Zm13 4h5l4 5v3h-9M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm12 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',ruler:'m3 16 13-13 5 5L8 21l-5-5Zm8-8 3 3m0-6 3 3m-9 3 3 3m-6 0 3 3',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',grid:'M3 3h6v6H3V3Zm12 0h6v6h-6V3ZM3 15h6v6H3v-6Zm12 0h6v6h-6v-6Z',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',filter:'M3 5h18M7 12h10M10 19h4M7 3v4M16 10v4M12 17v4',headphones:'M3 13v-1a9 9 0 0 1 18 0v5a4 4 0 0 1-4 4h-4M3 12h4v7H3v-7Zm14 0h4v7h-4v-7Z',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8M8 16h6'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.file}"/></svg>`;}
function hydrateIcons(root=document){root.querySelectorAll('i[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
