products.push({id:'SHESTIGRANNIK-001',category:'hexagon',grade:'По заявке',price:null,stock:null,acrossFlats:'По заявке',standard:'По согласованию',material:'Сталь',shape:'Шестигранная',title:'Шестигранник стальной'});
const categories={
 forging:{hash:'#catalog-pokovka',title:'Поковка стальная',family:'Чушки, заготовки, поковки',intro:'Стальные поковки оптом и в розницу. Подберите заготовку по марке стали, диаметру и стандарту. Уточните стоимость и сроки поставки у менеджера.',about:'Стальная поковка',paragraphs:['Поковка — заготовка для изготовления деталей машин и промышленного оборудования. Марку стали, форму и размеры выбирают с учётом условий эксплуатации и последующей обработки.','В каталоге представлены круглые поковки из различных марок стали. Используйте фильтры, чтобы найти нужный диаметр и стандарт, или сформируйте заявку на подбор.'],selection:'Как выбрать поковку',request:'Расчёт поковки по параметрам',banner:'Не нашли нужную поковку?',note:'Цены и наличие приведены по каталогу-образцу. Итоговую стоимость и доступность необходимо уточнить перед заказом.'},
 round:{hash:'#catalog-krug',title:'Круг стальной',family:'Сортовой прокат',intro:'Выберите стальной круг в каталоге или закажите подбор по вашим параметрам. Укажите длину и объём в заявке. Стоимость и наличие уточняются при заказе.',about:'Стальной круг',paragraphs:['Стальной круг — прокат круглого сечения для изготовления деталей, валов, осей и заготовок.','Добавьте нужную позицию в корзину и укажите длину, требуемый стандарт и количество в заявке. Для подбора другого круга дополнительно укажите марку стали и диаметр.'],selection:'Как заказать круг',request:'Расчёт стального круга',banner:'Нужен круг по вашим параметрам?',note:'Цена, наличие, длина и условия поставки — по запросу.'},
 square:{hash:'#catalog-kvadrat',title:'Квадрат стальной',family:'Сортовой прокат',intro:'Стальной квадрат по вашим параметрам. Укажите марку стали, размер стороны, длину и объём в заявке. Стоимость и наличие уточняются при подборе.',about:'Стальной квадрат',paragraphs:['Стальной квадрат — прокат с квадратным поперечным сечением для изготовления деталей, элементов конструкций и заготовок.','Для подбора укажите марку стали, размер стороны квадрата, длину, требуемый стандарт и количество. Добавьте позицию в корзину и внесите параметры в комментарий к заявке.'],selection:'Как заказать квадрат',request:'Расчёт стального квадрата',banner:'Нужен квадрат по вашим параметрам?',note:'Цена, наличие, марка стали, размер стороны и длина — по запросу.'},
 hexagon:{hash:'#catalog-shestigrannik',title:'Шестигранник стальной',family:'Сортовой прокат',intro:'Стальной шестигранник по вашим параметрам. Укажите марку стали, размер под ключ, длину и объём в заявке. Стоимость и наличие уточняются при подборе.',about:'Стальной шестигранник',paragraphs:['Стальной шестигранник — прокат с шестигранным поперечным сечением для изготовления крепежа, деталей и заготовок.','Для подбора укажите марку стали, размер под ключ, длину, требуемый стандарт и количество. Добавьте позицию в корзину и внесите параметры в комментарий к заявке.'],selection:'Как заказать шестигранник',request:'Расчёт стального шестигранника',banner:'Нужен шестигранник по вашим параметрам?',note:'Цена, наличие, марка стали, размер под ключ и длина — по запросу.'}
};
const groups=[['grade','Марка стали'],['diameter','Диаметр, мм'],['standard','НТД'],['material','Материал'],['shape','Форма']];
const state={category:categoryFromHash(),query:'',filters:{},sort:'default',view:'list',page:1,pageSize:8,quantities:{},cart:{}};
const $=sel=>document.querySelector(sel);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(value);
const quantity=value=>Math.min(1000000,Math.max(1,Math.floor(Number(value)||1)));
const plural=n=>n%10===1&&n%100!==11?'товар':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'товара':'товаров';
function status(p){return p.stock===true?'В наличии':p.stock===false?'Под заказ':'Уточнить наличие';}
function loadCart(){try{const saved=JSON.parse(localStorage.getItem('snabservis-demo-cart-v1')||'{}');products.forEach(p=>{if(saved&&Number(saved[p.id])>0)state.cart[p.id]=quantity(saved[p.id]);});}catch{state.cart={};}}
function saveCart(){try{localStorage.setItem('snabservis-demo-cart-v1',JSON.stringify(state.cart));}catch{}$('#cart-count').textContent=Object.keys(state.cart).length;$('#cart-button').setAttribute('aria-label',`Корзина, ${Object.keys(state.cart).length} позиций`);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}

function categoryFromHash(){return Object.keys(categories).find(key=>categories[key].hash===location.hash)||'forging';}
function sizeLabel(category=state.category){return category==='hexagon'?'Размер под ключ':category==='square'?'Сторона квадрата':'Диаметр';}
function sizeValue(p){return p.category==='hexagon'?p.acrossFlats:p.category==='square'?p.side:p.diameter;}
function attributeValue(p,key){return key==='diameter'?sizeValue(p):p[key];}
function requestedParameters(p){if(p.grade!=='По заявке'&&sizeValue(p)!=='По заявке')return 'Длину и требуемый стандарт';if(p.category==='round'&&p.grade!=='По заявке')return 'Диаметр, длину и требуемый стандарт';return p.category==='hexagon'?'Марку стали, размер под ключ, длину и требуемый стандарт':p.category==='square'?'Марку стали, размер стороны квадрата, длину и требуемый стандарт':'Марку стали, диаметр, длину и требуемый стандарт';}
function productDescription(p){return p.category==='forging'?'Стоимость и наличие взяты из каталога-образца и требуют подтверждения при оформлении заказа.':`${requestedParameters(p)} укажите в комментарии к заявке. Цена и наличие уточняются при подборе.`;}
function categoryProducts(){return products.filter(p=>p.category===state.category);}
function hasPrice(p){return typeof p.price==='number'&&Number.isFinite(p.price);}
function priceMarkup(p,totalQuantity=null){return hasPrice(p)?`<div class="price">${money(p.price*(totalQuantity===null?1:totalQuantity))} ₽${totalQuantity===null?'<small>/кг</small>':''}</div>`:'<div class="price price-request">По запросу</div>';}
function cartTotal(entries){return entries.some(p=>!hasPrice(p))?'Итого: по запросу':`Итого: ${money(entries.reduce((sum,p)=>sum+p.price*state.cart[p.id],0))} ₽`;}
function renderCategory(){
 const category=categories[state.category];
 document.title=`${category.title} в Санкт-Петербурге — Специальные стали Северо-Запада`;
 $('meta[name="description"]').content=category.intro;
 $('h1').textContent=category.title;$('#catalog-family').textContent=category.family;$('.breadcrumbs [aria-current="page"]').textContent=category.title;
 $('.catalog-intro p').textContent=category.intro;$('.price-note').textContent=category.note;
 $('#about h2').textContent=category.about;$('#about > div:first-child').querySelectorAll('p').forEach((p,i)=>p.textContent=category.paragraphs[i]);
 $('.technical-notes summary').innerHTML=esc(category.selection)+icon('chevron');
 $('.request-banner h2').textContent=category.banner;$('.request-banner [data-request]').dataset.request=category.request;
 $('.help-card [data-request]').dataset.request={forging:'Консультация по подбору поковки',round:'Консультация по подбору стального круга',square:'Консультация по подбору стального квадрата',hexagon:'Консультация по подбору стального шестигранника'}[state.category];
 const byRequest=!categoryProducts().some(p=>p.grade!=='По заявке');
 $('.stock-toggle').hidden=state.category!=='forging';
 $('#filter-form').hidden=byRequest;$('#filter-hint').hidden=!byRequest;$('#clear-filters').hidden=byRequest;$('#mobile-filter').hidden=byRequest;$('#filter-hint').textContent=state.category==='hexagon'?'Укажите марку стали, размер под ключ и длину в комментарии к заявке.':state.category==='square'?'Укажите марку стали, размер стороны квадрата и длину в комментарии к заявке.':'Укажите нужные марку стали, диаметр и длину в комментарии к заявке.';
 document.querySelectorAll('[data-category]').forEach(link=>{const active=link.dataset.category===state.category;link.classList.toggle('active-category',active);link.querySelector('i').hidden=!active;if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
}
function switchCategory(category,updateHash=true){
 if(!categories[category])return;
 state.category=category;state.query='';state.filters={};state.page=1;state.sort='default';$('#search').value='';$('#sort').value='default';
 initFilters();document.querySelector('#filter-form').reset();renderCategory();render();menuToggle(false);$('#filters').classList.remove('mobile-open');$('#mobile-filter').setAttribute('aria-expanded','false');
 if(updateHash){const hash=categories[category].hash;if(location.hash!==hash)history.pushState(null,'',hash);}
 $('#catalog').scrollIntoView({block:'start'});
}

function initFilters(){
 const visibleGroups=state.category==='forging'?groups:groups.filter(([key])=>key==='grade');
 $('#filter-groups').innerHTML=visibleGroups.map(([key,label],index)=>{const values=[...new Set(categoryProducts().map(p=>attributeValue(p,key)))].filter(value=>key!=='grade'||value!=='По заявке').sort((a,b)=>a.localeCompare(b,'ru',{numeric:true}));return `<details class="filter-group"${index===0||index===1?' open':''}><summary>${key==='diameter'?sizeLabel()+', мм':label}${icon('chevron')}</summary>${key==='grade'?'<input class="filter-search" type="search" placeholder="Найти марку" aria-label="Найти марку стали">':''}<div class="filter-options" data-group="${key}">${values.map(value=>`<label><input type="checkbox" name="${key}" value="${esc(value)}">${esc(value)}<span>${categoryProducts().filter(p=>attributeValue(p,key)===value).length}</span></label>`).join('')}</div></details>`;}).join('');
 $('.filter-search').addEventListener('input',e=>{$('[data-group="grade"]').querySelectorAll('label').forEach(l=>{l.hidden=!l.textContent.toLowerCase().includes(e.target.value.toLowerCase());l.style.display=l.hidden?'none':'';});});
}
function filtered(){let items=categoryProducts().filter(p=>{const q=state.query.toLocaleLowerCase('ru');if(q&&!`${p.title} ${p.id}`.toLocaleLowerCase('ru').includes(q))return false;if(state.filters.stock&&!p.stock)return false;return groups.every(([key])=>!state.filters[key]?.length||state.filters[key].includes(attributeValue(p,key)));});if(state.sort==='price-up')items.sort((a,b)=>(hasPrice(a)?a.price:Infinity)-(hasPrice(b)?b.price:Infinity));if(state.sort==='price-down')items.sort((a,b)=>(hasPrice(b)?b.price:-Infinity)-(hasPrice(a)?a.price:-Infinity));if(state.sort==='name')items.sort((a,b)=>a.title.localeCompare(b.title,'ru'));return items;}
function quantityControl(id,value,scope='product'){return `<div class="quantity-wrap"><div class="quantity"><button type="button" data-step="-1" data-id="${id}" data-scope="${scope}" aria-label="Уменьшить количество ${id}">−</button><input type="number" min="1" max="1000000" step="1" value="${value}" data-quantity="${id}" data-scope="${scope}" aria-label="Количество в килограммах ${id}"><button type="button" data-step="1" data-id="${id}" data-scope="${scope}" aria-label="Увеличить количество ${id}">+</button></div><span>кг</span></div>`;}
function render(){
 const items=filtered();const pages=Math.max(1,Math.ceil(items.length/state.pageSize));state.page=Math.min(state.page,pages);
 $('#result-count').textContent=`${items.length} ${plural(items.length)}`;$('#title-count').textContent=`${categoryProducts().length} ${plural(categoryProducts().length)}`;
 $('#products').className=`products ${state.view==='grid'?'grid':''}`;$('.table-labels').hidden=state.view==='grid'||items.length===0;
 $('#products').innerHTML=items.slice((state.page-1)*state.pageSize,state.page*state.pageSize).map(p=>`<article class="product-row" data-product="${p.id}"><div class="product-info"><img class="product-thumb" src="assets/mark.svg?v=4" alt="" width="62" height="65"><div><button class="product-title" data-detail="${p.id}">${esc(p.title)}</button><div class="product-meta"><span class="availability${p.stock!==true?' on-order':''}">${status(p)}</span><span class="sku">Арт. ${p.id}</span></div></div></div>${quantityControl(p.id,state.quantities[p.id]||1)}${priceMarkup(p)}<button class="product-order${state.cart[p.id]?' added':''}" data-cart-toggle="${p.id}" title="${state.cart[p.id]?'Удалить из корзины':'Добавить в корзину'}" aria-label="${state.cart[p.id]?'Убрать из корзины':'Заказать'}: ${esc(p.title)}">${icon(state.cart[p.id]?'close':'cart')}<span>${state.cart[p.id]?'Убрать':'Заказать'}</span></button></article>`).join('')||'<div class="empty-state"><h3>Товары не найдены</h3><p>Измените запрос или сбросьте фильтры.</p><button class="button" data-reset>Сбросить поиск и фильтры</button></div>';
 $('#page-summary').textContent=items.length?`${(state.page-1)*state.pageSize+1}–${Math.min(state.page*state.pageSize,items.length)} из ${items.length} товаров`:'';
 $('#pagination').innerHTML=items.length?Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.page===i+1?'active':''}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')+(state.page<pages?`<button class="next" data-page="${state.page+1}">Далее</button>`:''):'';
 $('#active-filters').innerHTML=(state.query?`<button class="filter-chip" data-clear-query>Поиск: ${esc(state.query)} ×</button>`:'')+groups.map(([key])=>(state.filters[key]||[]).map(v=>`<button class="filter-chip" data-remove-filter="${key}" data-value="${esc(v)}">${esc(v)} ×</button>`).join('')).join('')+(state.filters.stock?'<button class="filter-chip" data-remove-filter="stock">В наличии ×</button>':'');
 $('#list-view').classList.toggle('selected',state.view==='list');$('#grid-view').classList.toggle('selected',state.view==='grid');$('#list-view').setAttribute('aria-pressed',state.view==='list');$('#grid-view').setAttribute('aria-pressed',state.view==='grid');
}
function syncForm(){Array.from($('#filter-form').elements).forEach(el=>{if(el.type==='checkbox')el.checked=el.name==='stock'?!!state.filters.stock:(state.filters[el.name]||[]).includes(el.value);});}
function applyFilters(){const data=new FormData($('#filter-form'));state.filters={};groups.forEach(([key])=>{state.filters[key]=data.getAll(key);});state.filters.stock=state.category==='forging'&&data.has('stock');state.page=1;render();}
function reset(){state.filters={};state.query='';state.page=1;$('#search').value='';$('#filter-form').reset();$('.filter-search').value='';$('.filter-search').dispatchEvent(new Event('input'));render();}
function setQuantity(id,value,scope){const p=products.find(p=>p.id===id);if(!p)return;const q=quantity(value);if(scope==='cart'){state.cart[id]=q;saveCart();renderCart();}else{state.quantities[id]=q;document.querySelectorAll(`[data-quantity="${id}"][data-scope="product"]`).forEach(el=>el.value=q);}}
function addToCart(id,open=false){const p=products.find(p=>p.id===id);if(!p)return;state.cart[id]=quantity((state.cart[id]||0)+(state.quantities[id]||1));saveCart();render();if(open)renderCart();else toast(`${p.grade==='По заявке'?p.title:p.grade} · ${state.quantities[id]||1} кг добавлено в корзину`);}
function removeFromCart(id){const p=products.find(p=>p.id===id);if(!p||!state.cart[id])return;delete state.cart[id];saveCart();render();toast(`${p.title} удалён из корзины`);}
function openModal(html){$('#modal-content').innerHTML=html;hydrateIcons($('#modal'));if(!$('#modal').open)$('#modal').showModal();}
function renderCart(){const entries=products.filter(p=>state.cart[p.id]);openModal(`<h2 id="modal-title">Корзина <span class="title-count">${entries.length}</span></h2><p class="modal-description">Корзина сохраняется только в этом браузере. Цены в заявке предварительные.</p>${entries.length?`<div>${entries.map(p=>`<div class="basket-item"><div>${esc(p.title)}${quantityControl(p.id,state.cart[p.id],'cart')}</div><div>${priceMarkup(p,state.cart[p.id])}<button class="basket-remove" data-remove="${p.id}">Удалить</button></div></div>`).join('')}</div><div class="basket-bottom"><span>Без учёта доставки · ${money(entries.reduce((s,p)=>s+state.cart[p.id],0))} кг</span><strong>${cartTotal(entries)}</strong></div><div class="basket-actions"><button class="button button-outline" id="cart-download">Скачать список</button><button class="button" id="checkout">Сформировать заявку</button></div>`:'<div class="empty-state"><h3>В корзине пока пусто</h3><p>Добавьте нужные товары из каталога.</p><button class="button" data-close>Перейти к товарам</button></div>'}`);}
function renderDetail(id){const p=products.find(p=>p.id===id);if(!p)return;openModal(`<span class="eyebrow">АРТИКУЛ ${p.id}</span><h2 id="modal-title">${esc(p.title)}</h2><div class="detail-head"><img src="assets/mark.svg?v=4" alt="Специальные стали Северо-Запада"><div><span class="availability${p.stock!==true?' on-order':''}">${status(p)}</span>${priceMarkup(p)}</div></div><dl class="spec-list">${[['Марка стали',p.grade],[sizeLabel(p.category),/^\d+$/.test(sizeValue(p))?`${sizeValue(p)} мм`:sizeValue(p)],['Стандарт',p.standard],['Материал',p.material],['Форма',p.shape]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="modal-description">${esc(productDescription(p))}</p><div class="basket-actions">${quantityControl(p.id,state.quantities[p.id]||1)}<button class="button" data-detail-add="${p.id}">${icon('cart')}Добавить в корзину</button></div>`);}
function cartText(){
 const entries=products.filter(p=>state.cart[p.id]);
 return entries.map((p,i)=>`${i+1}. ${p.title}\nАртикул: ${p.id}; количество: ${state.cart[p.id]} кг; ${hasPrice(p)?`цена: ${p.price} руб./кг; сумма: ${p.price*state.cart[p.id]} руб.`:`цена и сумма: по запросу. ${requestedParameters(p)} необходимо указать в комментарии.`}`).join('\n\n')+(entries.length?`\n\n${cartTotal(entries)}\nБез учёта доставки. Цены и наличие требуют подтверждения.`:'');
}
function download(name,contents,type='text/plain;charset=utf-8'){const blob=new Blob(['\ufeff',contents],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function requestForm(subject,withCart=false){openModal(`<span class="eyebrow">ЗАЯВКА НА РАСЧЁТ</span><h2 id="modal-title">${esc(subject)}</h2><p class="modal-description">Заполните данные и скачайте готовую заявку. Автоматическая отправка менеджеру в этой версии не подключена.</p><form id="request-form" class="request-form"><label>Ваше имя<input name="name" autocomplete="name" placeholder="Как к вам обращаться" required maxlength="120"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" placeholder="+7 (___) ___-__-__" required minlength="7" maxlength="30" pattern="[+0-9()\u0020\u002D]{7,30}"></label><label>Электронная почта<input name="email" type="email" autocomplete="email" placeholder="mail@company.ru" maxlength="200"></label><label>Комментарий<textarea name="comment" placeholder="Марка стали, размеры, объём и пожелания к доставке" maxlength="3000"></textarea></label><p class="privacy-text">Данные останутся в скачанном файле и никуда не отправляются. Вы сможете проверить заявку перед отправкой.</p><button type="submit" class="button">${icon('download')}Скачать готовую заявку</button></form>`);$('#request-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);if(String(data.get('phone')).replace(/\D/g,'').length<7){form.elements.phone.setCustomValidity('Укажите номер телефона: не менее 7 цифр.');form.elements.phone.reportValidity();return;}download('Заявка-Специальные-стали-Северо-Запада.txt',`ЗАЯВКА — ${subject}\n\nИмя: ${data.get('name')}\nТелефон: ${data.get('phone')}\nEmail: ${data.get('email')||'Не указан'}\n\n${withCart?cartText()+'\n\n':''}Комментарий:\n${data.get('comment')||'—'}\n\nКаталог «Специальные стали Северо-Запада». Заявка автоматически не отправлялась.`);openModal(`<span class="eyebrow">ЗАЯВКА ПОДГОТОВЛЕНА</span><h2 id="modal-title">Файл готов к сохранению</h2><p class="modal-description">Заявка сформирована в формате TXT. Проверьте загрузки браузера, затем передайте файл менеджеру удобным способом. Автоматическая отправка не выполнялась.</p><button class="button" data-close>Вернуться к каталогу</button>`);});$('#request-form').elements.phone.addEventListener('input',e=>e.target.setCustomValidity(''));}
function showInfo(kind){const info={quality:['Документы и качество','Требования к материалу, испытаниям и сопроводительным документам согласовываются для каждой партии. Укажите необходимый ГОСТ и требования к сертификатам в заявке.'],location:['Санкт-Петербург','В этой версии представлен каталог Санкт-Петербурга. Адрес из примера: набережная Обводного канала, 134–136–138, литера В.Г., офис 6.\nОтдел продаж: +7 (812) 213-00-40.'],privacy:['Обработка данных','Это демонстрационный каталог. Корзина сохраняется локально в вашем браузере. Данные формы используются только для формирования скачиваемой заявки и не передаются на сервер. Чтобы удалить корзину, удалите товары из неё или очистите данные сайта в браузере.']}[kind];if(info)openModal(`<h2 id="modal-title">${info[0]}</h2><p class="modal-description">${esc(info[1]).replace(/\n/g,'<br>')}</p><button class="button button-outline" data-close>Понятно</button>`);}
function menuToggle(force){const open=force===undefined?$('#catalog-menu').hidden:force;$('#catalog-menu').hidden=!open;$('#catalog-menu-button').setAttribute('aria-expanded',String(open));}
document.addEventListener('click',e=>{
 const target=e.target.closest('button,a');if(!target)return;
 if(target.dataset.cartToggle){const id=target.dataset.cartToggle;if(state.cart[id])removeFromCart(id);else addToCart(id);$(`[data-cart-toggle="${id}"]`)?.focus({preventScroll:true});}
 if(target.dataset.detail)renderDetail(target.dataset.detail);
 if(target.dataset.detailAdd){addToCart(target.dataset.detailAdd);renderCart();}
 if(target.dataset.remove){removeFromCart(target.dataset.remove);renderCart();}
 if(target.dataset.step){const scope=target.dataset.scope,id=target.dataset.id,current=scope==='cart'?state.cart[id]:state.quantities[id]||1;setQuantity(id,current+Number(target.dataset.step),scope);}
 if(target.dataset.page){state.page=Number(target.dataset.page);render();$('.catalog-controls').scrollIntoView({block:'start',behavior:'smooth'});}
 if(target.hasAttribute('data-reset'))reset();
 if(target.hasAttribute('data-clear-query')){state.query='';$('#search').value='';state.page=1;render();}
 if(target.dataset.removeFilter){const key=target.dataset.removeFilter;if(key==='stock')delete state.filters.stock;else state.filters[key]=state.filters[key].filter(v=>v!==target.dataset.value);syncForm();state.page=1;render();}
 if(target.dataset.request)requestForm(target.dataset.request);
 if(target.dataset.info)showInfo(target.dataset.info);
 if(target.hasAttribute('data-close')||target.closest('.modal-close'))$('#modal').close();
 if(target.dataset.category){e.preventDefault();switchCategory(target.dataset.category);}
 if(target.dataset.quick){switchCategory('forging');reset();const type=target.dataset.quick;if(type==='stock')state.filters.stock=true;if(type==='round')state.filters.shape=['Круглая'];if(type==='construction')state.filters.material=['Конструкционная сталь'];syncForm();render();menuToggle(false);$('#catalog').scrollIntoView();}
 if(target.id==='cart-download'){download('Список-товаров.txt',cartText());toast('Список товаров подготовлен');}
 if(target.id==='checkout')requestForm('Расчёт заказа',true);
});
document.addEventListener('change',e=>{if(e.target.dataset.quantity)setQuantity(e.target.dataset.quantity,e.target.value,e.target.dataset.scope);});
$('#catalog-menu-button').addEventListener('click',()=>menuToggle());$('#breadcrumb-catalog').addEventListener('click',()=>menuToggle(true));$('#breadcrumb-metal').addEventListener('click',()=>menuToggle(true));
document.addEventListener('keydown',e=>{if(e.key==='Escape')menuToggle(false);});
document.addEventListener('click',e=>{if(!e.target.closest('header')&&!e.target.closest('.breadcrumbs'))menuToggle(false);});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();state.query=$('#search').value.trim();state.page=1;render();});
$('#search').addEventListener('input',e=>{state.query=e.target.value.trim();state.page=1;render();});
$('#sort').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;render();});
$('#list-view').addEventListener('click',()=>{state.view='list';render();});$('#grid-view').addEventListener('click',()=>{state.view='grid';render();});
$('#filter-form').addEventListener('change',e=>{if(state.category!=='forging'&&e.target.name==='grade')applyFilters();});
$('#filter-form').addEventListener('submit',e=>{e.preventDefault();applyFilters();$('#filters').classList.remove('mobile-open');$('#mobile-filter').setAttribute('aria-expanded','false');});
$('#clear-filters').addEventListener('click',reset);
$('#mobile-filter').setAttribute('aria-expanded','false');$('#mobile-filter').setAttribute('aria-controls','filters');$('#mobile-filter').addEventListener('click',()=>{const visible=$('#filters').classList.toggle('mobile-open');$('#mobile-filter').setAttribute('aria-expanded',String(visible));if(visible)$('#filters').scrollIntoView({block:'start'});});
$('#cart-button').addEventListener('click',renderCart);
$('#price-download').addEventListener('click',()=>{const quote=s=>`"${String(s).replace(/"/g,'""')}"`;const csv=[['Артикул','Наименование','Марка стали',`${sizeLabel()}, мм`,'НТД','Цена, руб./кг','Наличие (по образцу)'],...filtered().map(p=>[p.id,p.title,p.grade,sizeValue(p),p.standard,hasPrice(p)?p.price:'По запросу',status(p)])].map(row=>row.map(quote).join(';')).join('\r\n');download({forging:'Прайс-лист-поковки.csv',round:'Прайс-лист-круг.csv',square:'Прайс-лист-квадрат.csv',hexagon:'Прайс-лист-шестигранник.csv'}[state.category],csv,'text/csv;charset=utf-8');toast('Прайс-лист выбранных товаров подготовлен');});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close();}});
$('#delivery').addEventListener('click',()=>{});document.querySelector('a[href="#delivery"]').addEventListener('click',()=>$('#delivery').open=true);
window.addEventListener('hashchange',()=>{if(Object.values(categories).some(category=>category.hash===location.hash)||location.hash===''||location.hash==='#')switchCategory(categoryFromHash(),false);});
hydrateIcons();initFilters();loadCart();saveCart();renderCategory();render();
